SRC_REFLEXION = {"title": "Reflexion: Language Agents with Verbal Reinforcement Learning (paper)", "url": "https://arxiv.org/abs/2303.11366"}
SRC_LG = {"title": "LangGraph documentation", "url": "https://langchain-ai.github.io/langgraph/"}
SRC_ANTH = {"title": "Anthropic: Building effective agents", "url": "https://www.anthropic.com/engineering/building-effective-agents"}

SAFE_CALC = "import ast, operator\n\nOPS = {ast.Add: operator.add, ast.Sub: operator.sub, ast.Mult: operator.mul, ast.Div: operator.truediv}\n\ndef calculator(expr):\n    def ev(n):\n        if isinstance(n, ast.Constant) and isinstance(n.value, (int, float)):\n            return n.value\n        if isinstance(n, ast.BinOp) and type(n.op) in OPS:\n            return OPS[type(n.op)](ev(n.left), ev(n.right))\n        raise ValueError('unsupported expression')       # nothing but numbers and + - * / is allowed\n    return str(ev(ast.parse(expr, mode='eval').body))\n"

